"""QMP ``screendump`` capture, with an honest PNG/PPM fallback.

``screendump`` writes to a **host** file; it does not return image bytes. Two consequences
shape this module:

* the filename is generated by the service and never accepted from the agent, and
* the file is read, bounded, optionally re-encoded, then deleted — a captured frame is
  transient by default rather than a growing pile of screenshots on disk.

The PNG → PPM fallback fires only for a QMP error that names the ``format`` argument.
A missing file, a full disk or a dead VM are *different* failures and are reported as
such, because treating them as "this build lacks libpng" would hide real breakage.
"""

from __future__ import annotations

import io
import logging
import time
from pathlib import Path

from PIL import Image

from ..config import CaptureConfig
from ..errors import ErrorCode, PaletteError, QmpCommandError
from ..models import Size
from ..qmp.client import QmpClient
from .base import CapturedImage

logger = logging.getLogger("palette.capture")

#: Guard against a decompression bomb from an unexpected display surface.
MAX_FRAMEBUFFER_PIXELS = 8192 * 4320
_PNG_MAGIC = b"\x89PNG\r\n\x1a\n"
_PPM_MAGIC = (b"P6", b"P3", b"P5", b"P2")


class QmpCaptureBackend:
    """Capture through the private QMP channel."""

    def __init__(self, client: QmpClient, config: CaptureConfig) -> None:
        self._client = client
        self._config = config
        #: ``None`` until proven otherwise; set to False after a format rejection so the
        #: expensive failing call is only paid once per VM instance.
        self._png_supported: bool | None = None

    @property
    def png_supported(self) -> bool | None:
        return self._png_supported

    async def capture(self, *, display_id: str, head: int, sink: Path) -> CapturedImage:
        started = time.perf_counter()
        sink.parent.mkdir(parents=True, exist_ok=True)
        sink.unlink(missing_ok=True)

        format_used = "ppm"
        if self._config.prefer_format == "png" and self._png_supported is not False:
            try:
                await self._screendump(sink, display_id, head, fmt="png")
                self._png_supported = True
                format_used = "png"
            except QmpCommandError as exc:
                if not _is_format_rejection(exc):
                    raise _capture_error(exc) from exc
                self._png_supported = False
                if not self._config.allow_ppm_fallback:
                    raise PaletteError(
                        ErrorCode.UNSUPPORTED_CAPABILITY,
                        "this QEMU build cannot write PNG screendumps and PPM fallback is disabled",
                    ) from exc
                logger.info("PNG screendump rejected by this build; falling back to PPM")

        if format_used == "ppm":
            try:
                await self._screendump(sink, display_id, head, fmt=None)
            except QmpCommandError as exc:
                raise _capture_error(exc) from exc

        raw = self._read_and_cleanup(sink)
        return self._encode(raw, format_used=format_used, sink=sink, started=started)

    # -- internals -------------------------------------------------------------------
    async def _screendump(self, sink: Path, display_id: str, head: int, *, fmt: str | None) -> None:
        arguments: dict[str, object] = {
            "filename": str(sink),
            "device": display_id,
            "head": head,
        }
        if fmt is not None:
            arguments["format"] = fmt
        await self._client.execute("screendump", arguments, timeout=self._config.timeout_seconds)

    def _read_and_cleanup(self, sink: Path) -> bytes:
        if not sink.is_file():
            # The command reported success but no file exists: that is an I/O or
            # lifecycle problem, never a format problem.
            raise PaletteError(
                ErrorCode.CAPTURE_FAILED,
                "screendump reported success but produced no file",
            )
        try:
            data = sink.read_bytes()
        except OSError as exc:
            raise PaletteError(
                ErrorCode.CAPTURE_FAILED, "the capture file could not be read"
            ) from exc
        if not self._config.keep_frames:
            try:
                sink.unlink(missing_ok=True)
            except OSError:  # pragma: no cover - Windows file lock races
                logger.debug("could not remove the transient capture file")
        return data

    def _encode(self, raw: bytes, *, format_used: str, sink: Path, started: float) -> CapturedImage:
        if not raw:
            raise PaletteError(ErrorCode.CAPTURE_FAILED, "the capture file was empty")
        detected = _detect_format(raw)
        if detected == "png":
            format_used = "png"
        elif detected == "ppm":
            format_used = "ppm"
        else:
            raise PaletteError(ErrorCode.CAPTURE_FAILED, "the capture file is neither PNG nor PPM")

        try:
            with Image.open(io.BytesIO(raw)) as image:
                image.load()
                native = Size(width=image.width, height=image.height)
                if native.width * native.height > MAX_FRAMEBUFFER_PIXELS:
                    raise PaletteError(
                        ErrorCode.CAPTURE_TOO_LARGE,
                        "the framebuffer is larger than this service will decode",
                        details={"width": native.width, "height": native.height},
                    )
                png_bytes, image_size, scaled = self._render(image)
        except PaletteError:
            raise
        except Exception as exc:
            raise PaletteError(
                ErrorCode.CAPTURE_FAILED, f"the capture could not be decoded: {type(exc).__name__}"
            ) from exc

        duration_ms = int((time.perf_counter() - started) * 1000)
        return CapturedImage(
            png_bytes=png_bytes,
            native_size=native,
            image_size=image_size,
            format_used=format_used,
            scaled=scaled,
            duration_ms=duration_ms,
            source_path=sink if self._config.keep_frames else None,
        )

    def _render(self, image: Image.Image) -> tuple[bytes, Size, bool]:
        """Re-encode to PNG, shrinking only as far as the configured limits require."""
        working = image.convert("RGB") if image.mode not in ("RGB", "RGBA") else image
        max_edge = self._config.max_long_edge
        scaled = False
        if max(working.width, working.height) > max_edge:
            working, scaled = _downscale(working, max_edge)

        payload = _to_png_bytes(working)
        # A long edge limit usually keeps us under the byte limit too; if not, shrink
        # further and keep the advertised size in step with what was actually produced.
        attempts = 0
        while len(payload) > self._config.max_bytes and attempts < 4:
            next_edge = max(320, int(max(working.width, working.height) * 0.8))
            if next_edge >= max(working.width, working.height):
                break
            working, _ = _downscale(working, next_edge)
            scaled = True
            payload = _to_png_bytes(working)
            attempts += 1

        if len(payload) > self._config.max_bytes:
            raise PaletteError(
                ErrorCode.CAPTURE_TOO_LARGE,
                "the encoded capture still exceeds the configured byte limit",
                details={"max_bytes": self._config.max_bytes},
            )
        return payload, Size(width=working.width, height=working.height), scaled


def _to_png_bytes(image: Image.Image) -> bytes:
    buffer = io.BytesIO()
    image.save(buffer, format="PNG", optimize=True)
    return buffer.getvalue()


def _downscale(image: Image.Image, max_edge: int) -> tuple[Image.Image, bool]:
    ratio = max_edge / max(image.width, image.height)
    width = max(2, int(image.width * ratio))
    height = max(2, int(image.height * ratio))
    if width == image.width and height == image.height:
        return image, False
    return image.resize((width, height), Image.Resampling.LANCZOS), True


def _detect_format(raw: bytes) -> str:
    if raw.startswith(_PNG_MAGIC):
        return "png"
    if raw[:2] in _PPM_MAGIC:
        return "ppm"
    return "unknown"


def _is_format_rejection(exc: QmpCommandError) -> bool:
    """True only when QEMU's own reply blames the ``format``/PNG argument."""
    description = exc.description.lower()
    if "format" not in description and "png" not in description:
        return False
    return (
        any(
            token in description
            for token in (
                "not supported",
                "unsupported",
                "unknown parameter",
                "invalid parameter",
                "expects",
            )
        )
        or exc.qmp_class == "CommandNotFound"
    )


def _capture_error(exc: QmpCommandError) -> PaletteError:
    return PaletteError(
        ErrorCode.CAPTURE_FAILED,
        "QMP screendump failed",
        details={"qmp_class": exc.qmp_class},
    )
